// AppContext already holds user + theme. This PR adds a live
// notifications count that ticks every few seconds via polling.
 function AppProvider({ children }: { children: React.ReactNode }) {
   const [user, setUser] = useState<User | null>(null);
   const [theme, setTheme] = useState<Theme>("light");
+  const [notifCount, setNotifCount] = useState(0);
+  useEffect(() => {
+    const id = setInterval(() => setNotifCount((c) => c + pollDelta()), 4000);
+    return () => clearInterval(id);
+  }, []);
   return (
-    <AppContext.Provider value={{ user, setUser, theme, setTheme }}>
+    <AppContext.Provider value={{ user, setUser, theme, setTheme, notifCount, setNotifCount }}>
       {children}
     </AppContext.Provider>
   );
 }
 // <ThemeToggle>, <Cart>, <ProfileMenu> all read useContext(AppContext)
